def transform_general(grid):
    h, w = len(grid), len(grid[0])
    if h % 2 == 1 and len(set(grid[h//2])) == 1:
        sep = h // 2
        a, b = grid[:sep], grid[sep+1:]
        axis = 'h'
    elif w % 2 == 1 and all(len({grid[r][w//2] for r in range(h)}) == 1 for _ in [0]):
        sep = w // 2
        a = [row[:sep] for row in grid]
        b = [row[sep+1:] for row in grid]
        axis = 'v'
    else:
        raise ValueError('no center separator')
    ca, cb = {v for row in a for v in row}, {v for row in b for v in row}
    common = next(iter(ca & cb))
    if axis == 'h':
        return [[3 if x == common and y == common else common for x,y in zip(ar,br)] for ar,br in zip(a,b)]
    return [[3 if x == common and y == common else common for x,y in zip(ar,br)] for ar,br in zip(a,b)]
